-- Alocacao opcional FEFO sem obrigar produtos comuns.
create table commerce_sale_lot_allocations(id uuid primary key default gen_random_uuid(),business_id uuid not null,owner_id uuid not null,sale_id uuid not null,sale_item_id uuid not null,lot_id uuid not null,quantidade numeric(14,4) not null check(quantidade>0),quantidade_devolvida numeric(14,4) not null default 0 check(quantidade_devolvida>=0 and quantidade_devolvida<=quantidade),created_at timestamptz not null default now(),unique(id,business_id,owner_id),foreign key(business_id,owner_id) references commerce_businesses(id,owner_id) on delete cascade,foreign key(sale_id,business_id,owner_id) references commerce_sales(id,business_id,owner_id),foreign key(sale_item_id) references commerce_sale_items(id),foreign key(lot_id,business_id,owner_id) references commerce_stock_lots(id,business_id,owner_id));
create index commerce_sale_lot_item_idx on commerce_sale_lot_allocations(sale_item_id);
alter table commerce_sale_lot_allocations enable row level security;
create policy commerce_sale_lot_allocations_module on commerce_sale_lot_allocations for all using(owner_id=commerce_owner_atual() and (commerce_tem_modulo('estoque') or commerce_tem_modulo('vendas'))) with check(owner_id=commerce_owner_atual() and (commerce_tem_modulo('estoque') or commerce_tem_modulo('vendas')));
create function commerce_alocar_lotes_venda() returns trigger language plpgsql security invoker set search_path=public as $$declare i commerce_sale_items%rowtype;l commerce_stock_lots%rowtype;r numeric(14,4);u numeric(14,4);begin if old.status='aberta' and new.status='concluida' then for i in select * from commerce_sale_items where sale_id=new.id loop r:=i.quantidade;for l in select * from commerce_stock_lots where product_id=i.product_id and owner_id=new.owner_id and quantidade_atual>0 and (i.variant_id is null or variant_id=i.variant_id) order by validade asc nulls last,created_at,id for update loop exit when r<=0;u:=least(r,l.quantidade_atual);insert into commerce_sale_lot_allocations(business_id,owner_id,sale_id,sale_item_id,lot_id,quantidade) values(new.business_id,new.owner_id,new.id,i.id,l.id,u);update commerce_stock_lots set quantidade_atual=quantidade_atual-u where id=l.id;r:=r-u;end loop;end loop;elsif old.status='concluida' and new.status='cancelada' then update commerce_stock_lots l set quantidade_atual=l.quantidade_atual+(a.quantidade-a.quantidade_devolvida) from commerce_sale_lot_allocations a where a.sale_id=new.id and a.lot_id=l.id and a.quantidade>a.quantidade_devolvida;update commerce_sale_lot_allocations set quantidade_devolvida=quantidade where sale_id=new.id;end if;return new;end;$$;
create trigger commerce_sale_lot_fefo before update of status on commerce_sales for each row execute function commerce_alocar_lotes_venda();
create function commerce_restaurar_lote_devolucao() returns trigger language plpgsql security invoker set search_path=public as $$declare a commerce_sale_lot_allocations%rowtype;r numeric(14,4):=new.quantidade;u numeric(14,4);begin for a in select * from commerce_sale_lot_allocations where sale_item_id=new.sale_item_id and quantidade>quantidade_devolvida order by created_at,id for update loop exit when r<=0;u:=least(r,a.quantidade-a.quantidade_devolvida);update commerce_stock_lots set quantidade_atual=quantidade_atual+u where id=a.lot_id;update commerce_sale_lot_allocations set quantidade_devolvida=quantidade_devolvida+u where id=a.id;r:=r-u;end loop;return new;end;$$;
create trigger commerce_return_lot_stock after insert on commerce_sale_return_items for each row execute function commerce_restaurar_lote_devolucao();
